/**
 * Entitlements engine — single source of truth for "what is this org allowed
 * to do right now?". Backed by the embedded plans catalog + the Subscription
 * row in the database. Safe to call from any route or job; failure-mode is
 * fail-closed for paid features but fail-open for the free tier so a degraded
 * billing system never bricks day-1 onboarding.
 *
 * Generated by platform-generator (Tier 10 — Pricing & Monetization).
 */
const prisma = require('./prisma');

// Plans catalog is generated at build-time from registry/plans.json with
// industry overrides already applied for industry=home-services.
const PLANS = {"currency":"USD","trial_days_default":14,"tiers":[{"id":"free","name":"Free","price_cents_monthly":0,"price_cents_yearly":0,"trial_days":0,"stripe_price_monthly":null,"stripe_price_yearly":null,"limits":{"seats":1,"records_per_month":50,"api_calls_per_month":1000,"storage_gb":1,"ai_tokens_per_month":50000,"webhooks":1,"data_retention_days":30},"entitlements":{"sso":false,"audit_log":false,"api_access":true,"custom_branding":false,"priority_support":false,"ai_features":true,"advanced_analytics":false,"data_export":true,"webhooks":true,"team_collaboration":false}},{"id":"starter","name":"Starter","price_cents_monthly":29900,"price_cents_yearly":287040,"trial_days":14,"stripe_price_monthly":null,"stripe_price_yearly":null,"limits":{"seats":5,"records_per_month":1000,"api_calls_per_month":50000,"storage_gb":25,"ai_tokens_per_month":1000000,"webhooks":5,"data_retention_days":90},"entitlements":{"sso":false,"audit_log":true,"api_access":true,"custom_branding":false,"priority_support":false,"ai_features":true,"advanced_analytics":true,"data_export":true,"webhooks":true,"team_collaboration":true}},{"id":"pro","name":"Professional","price_cents_monthly":69900,"price_cents_yearly":671040,"trial_days":14,"stripe_price_monthly":null,"stripe_price_yearly":null,"limits":{"seats":25,"records_per_month":10000,"api_calls_per_month":500000,"storage_gb":200,"ai_tokens_per_month":10000000,"webhooks":25,"data_retention_days":365},"entitlements":{"sso":true,"audit_log":true,"api_access":true,"custom_branding":true,"priority_support":true,"ai_features":true,"advanced_analytics":true,"data_export":true,"webhooks":true,"team_collaboration":true}},{"id":"enterprise","name":"Enterprise","price_cents_monthly":0,"price_cents_yearly":0,"contact_sales":true,"trial_days":30,"stripe_price_monthly":null,"stripe_price_yearly":null,"limits":{"seats":-1,"records_per_month":-1,"api_calls_per_month":-1,"storage_gb":-1,"ai_tokens_per_month":-1,"webhooks":-1,"data_retention_days":2555},"entitlements":{"sso":true,"audit_log":true,"api_access":true,"custom_branding":true,"priority_support":true,"ai_features":true,"advanced_analytics":true,"data_export":true,"webhooks":true,"team_collaboration":true,"dedicated_tenancy":true,"custom_dpa":true,"soc2_report_access":true,"named_csm":true}}],"metering":{"billable_meters":["records_per_month","api_calls_per_month","ai_tokens_per_month"],"overage_cents":{"records_per_month":50,"api_calls_per_month":1,"ai_tokens_per_month":1},"aggregation_window":"month"},"industry_applied":"home-services","archetype":"agent-orchestrator"};

// Allow operators to inject Stripe price IDs at runtime via env vars
// (populated by `npm run stripe:setup`) so we don't need a rebuild after
// provisioning Stripe products. Format: STRIPE_PRICE_<TIER>_MONTHLY,
// STRIPE_PRICE_<TIER>_YEARLY (tier id upper-cased).
for (const tier of (PLANS.tiers || [])) {
  const k = String(tier.id || '').toUpperCase();
  const m = process.env[`STRIPE_PRICE_${k}_MONTHLY`];
  const y = process.env[`STRIPE_PRICE_${k}_YEARLY`];
  if (m) tier.stripe_price_monthly = m;
  if (y) tier.stripe_price_yearly = y;
}

const TIERS_BY_ID = Object.fromEntries((PLANS.tiers || []).map(t => [t.id, t]));
const FREE_TIER_ID = (PLANS.tiers && PLANS.tiers[0] && PLANS.tiers[0].id) || 'free';

function getTier(tierId) {
  return TIERS_BY_ID[tierId] || TIERS_BY_ID[FREE_TIER_ID];
}

function listPlans() {
  return PLANS;
}

/**
 * Resolve the active subscription for an org. Returns:
 *   { tier, status, trialEndsAt, currentPeriodStart, currentPeriodEnd, cancelAt }
 * Falls back to the free tier when there is no subscription row.
 */
const LIVE_STATUSES = ['trialing', 'active', 'past_due', 'grace'];

async function getActiveSubscription(orgId) {
  if (!orgId) return { tier: getTier(FREE_TIER_ID), status: 'none' };
  // Subscription.orgId is @unique, so there is at most one row per org — this
  // IS the org's subscription and no ordering or tie-breaking is needed.
  //
  // Deliberately unfiltered by status. Filtering to live statuses (as this
  // did originally) meant a suspended or canceled row looked identical to
  // having no subscription at all, so `status` could never come back as
  // 'suspended'/'canceled' — while `can()`, `getLimit()` and
  // middleware/entitlements.js#blockIfSuspended all branch on exactly those
  // values. Every one of those branches was unreachable, and suspended orgs
  // silently kept working. Reporting the real status is what makes them run.
  //
  // The paid tier is granted only for a live status, so reading the row
  // unfiltered cannot accidentally hand paid features to a non-live
  // subscription in some state nobody enumerated.
  const sub = await prisma.subscription.findFirst({ where: { orgId } });
  if (!sub) return { tier: getTier(FREE_TIER_ID), status: 'none' };
  return {
    tier: LIVE_STATUSES.includes(sub.status) ? getTier(sub.planId) : getTier(FREE_TIER_ID),
    status: sub.status,
    trialEndsAt: sub.trialEndsAt,
    currentPeriodStart: sub.currentPeriodStart,
    currentPeriodEnd: sub.currentPeriodEnd,
    cancelAt: sub.cancelAt,
    stripeSubId: sub.stripeSubId,
  };
}

/** Boolean entitlement check. Unknown features default to false (fail-closed). */
async function can(orgId, feature) {
  const sub = await getActiveSubscription(orgId);
  // Suspended subs lose all paid entitlements but keep free-tier rights.
  const effectiveTier = sub.status === 'suspended' || sub.status === 'canceled'
    ? getTier(FREE_TIER_ID)
    : sub.tier;
  return Boolean(effectiveTier.entitlements && effectiveTier.entitlements[feature]);
}

/**
 * Numeric limit lookup (-1 = unlimited). Returns 0 for unknown meters.
 * Pass `knownTier` (e.g. req.tenant.plan, already resolved by
 * middleware/tenant.js#attachTenant for any route that ran it) to skip a
 * redundant getActiveSubscription() query — the same resolution
 * attachTenant already just did for this request.
 */
async function getLimit(orgId, meter, knownTier) {
  const tier = knownTier || await (async () => {
    const sub = await getActiveSubscription(orgId);
    return sub.status === 'suspended' || sub.status === 'canceled' ? getTier(FREE_TIER_ID) : sub.tier;
  })();
  if (!tier.limits || !(meter in tier.limits)) return 0;
  return Number(tier.limits[meter]);
}

/**
 * Period-aware usage check. Returns:
 *   { allowed, used, limit, remaining, overage_cents_per_unit }
 */
async function checkUsage(orgId, meter, requested = 1, knownTier) {
  const limit = await getLimit(orgId, meter, knownTier);
  if (limit === -1) {
    return { allowed: true, used: 0, limit: -1, remaining: Infinity, overage_cents_per_unit: 0 };
  }

  const period = currentPeriodKey();
  const counter = await prisma.usageCounter.findUnique({
    where: { orgId_meter_period: { orgId: orgId || '', meter, period } },
  }).catch(() => null);

  const used = counter ? Number(counter.value) : 0;
  const remaining = Math.max(0, limit - used);
  const allowed = (used + Number(requested)) <= limit;
  const overage = (PLANS.metering && PLANS.metering.overage_cents
                   && PLANS.metering.overage_cents[meter]) || 0;
  return { allowed, used, limit, remaining, overage_cents_per_unit: overage };
}

/**
 * Gauge-style seat check — unlike checkUsage()'s monthly-resetting flow
 * meters (records_per_month, api_calls_per_month, ai_tokens_per_month),
 * seat count is a live headcount, not something that should reset on the
 * 1st of the month. Counts *active* OrgMembership rows directly rather
 * than going through UsageCounter, which would incorrectly let a
 * full-seats org invite unlimited new members every time the monthly
 * period rolled over.
 */
async function checkSeats(orgId, additional = 1, knownTier) {
  const limit = await getLimit(orgId, 'seats', knownTier);
  if (limit === -1) return { allowed: true, used: 0, limit: -1, remaining: Infinity };
  const used = await prisma.orgMembership.count({ where: { orgId, status: 'active' } });
  const remaining = Math.max(0, limit - used);
  return { allowed: (used + Number(additional)) <= limit, used, limit, remaining };
}

/**
 * Gauge-style storage check, same rationale as checkSeats(): bytes on disk
 * are a live total, not a monthly flow, so routing them through
 * UsageCounter would let a full org upload its whole quota again every
 * time the period rolled over. Sums the two models that actually own
 * uploaded bytes. Rows predating the fileSizeBytes column count as 0
 * rather than blocking the org — undercounting legacy rows is the
 * conservative failure here, since the alternative is refusing uploads
 * based on a number we can't compute.
 */
const BYTES_PER_GB = 1024 * 1024 * 1024;

async function checkStorageBytes(orgId, additionalBytes = 0, knownTier) {
  const limitGb = await getLimit(orgId, 'storage_gb', knownTier);
  if (limitGb === -1) return { allowed: true, used: 0, limit: -1, remaining: Infinity };
  const limitBytes = limitGb * BYTES_PER_GB;
  const [docs, evidence] = await Promise.all([
    prisma.sourceDocument.aggregate({ where: { orgId }, _sum: { file_size_bytes: true } }).catch(() => null),
    prisma.evidenceItem.aggregate({ where: { orgId }, _sum: { fileSizeBytes: true } }).catch(() => null),
  ]);
  // Clamped at zero defensively: a negative total would silently grant
  // headroom rather than fail closed, so even if some future path writes a
  // bad size the quota degrades to "count nothing" instead of "allow
  // anything". The columns are server-set and not client-writable.
  const used = Math.max(0,
    Number(docs?._sum?.file_size_bytes || 0) + Number(evidence?._sum?.fileSizeBytes || 0));
  const remaining = Math.max(0, limitBytes - used);
  return {
    allowed: (used + Number(additionalBytes)) <= limitBytes,
    used, limit: limitBytes, limitGb, remaining,
  };
}

/**
 * Gauge-style webhook-endpoint check — a live count of configured
 * endpoints, for the same reason seats and storage are gauges.
 *
 * The `webhooks` limit is per PLAN, i.e. per org, but the Webhook model is
 * user-scoped (`userId`, no orgId column and no `user` relation to filter
 * through), so the org's members are resolved first and the count is taken
 * across all of them. Counting per-user instead would let an N-seat org
 * create N times its actual plan limit.
 */
async function checkWebhooks(orgId, additional = 1, knownTier) {
  // Guard the falsy case explicitly: `findMany({ where: { orgId: null } })`
  // is `WHERE orgId IS NULL`, which would pool every org-less user in the
  // deployment into one shared bucket — the first of them to add a webhook
  // would block all the others, and their usage would be cross-attributed.
  if (!orgId) return { allowed: false, used: 0, limit: 0, remaining: 0 };
  const limit = await getLimit(orgId, 'webhooks', knownTier);
  if (limit === -1) return { allowed: true, used: 0, limit: -1, remaining: Infinity };
  const members = await prisma.user.findMany({ where: { orgId }, select: { id: true } });
  const used = members.length
    ? await prisma.webhook.count({ where: { userId: { in: members.map(u => u.id) } } })
    : 0;
  const remaining = Math.max(0, limit - used);
  return { allowed: (used + Number(additional)) <= limit, used, limit, remaining };
}

/** Current monthly period key in UTC, e.g. "2026-04". */
function currentPeriodKey() {
  const d = new Date();
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  return `${y}-${m}`;
}

module.exports = {
  PLANS,
  FREE_TIER_ID,
  // Exported so the Stripe status map can be tested against the actual list
  // that gates paid access, rather than a copy of it that can drift.
  LIVE_STATUSES,
  getTier,
  listPlans,
  getActiveSubscription,
  can,
  getLimit,
  checkUsage,
  checkSeats,
  checkStorageBytes,
  checkWebhooks,
  currentPeriodKey,
  BYTES_PER_GB,
};

